theorem thm_GAR : 
  let consecutive_decreasing_numbers : Set ℕ := 
    {n | ∃ a : ℕ, 1 ≤ a ∧ a ≤ 9 ∧ n = 111 * a - 12}
  let f : ℕ → ℝ := fun n => 2 * (n : ℝ)^2 + 8 * (n : ℝ) + 33 - 3 * Real.sqrt ((n : ℝ)^2 + 4 * (n : ℝ) + 9)
  ∃ min_val : ℝ, (∀ n ∈ consecutive_decreasing_numbers, f n ≥ min_val) ∧ 
                  (∃ n ∈ consecutive_decreasing_numbers, f n = min_val) := by
